def backfill_provenance(apps, schema_editor):
    """Flag existing synthetic entries, queue practitioner entries for review, fill keys."""
    from apps.medications.catalog import dedupe_key

    Medication = apps.get_model("medications", "Medication")
    for med in Medication.objects.all():
        med.is_synthetic = med.source == "synthetic_test"
        if med.source == "practitioner":
            med.review_status = "pending"
        med.dedupe_key = dedupe_key(med.name, med.strength, med.dosage_form, med.manufacturer)
        med.save(update_fields=["is_synthetic", "review_status", "dedupe_key"])


